INSERT INTO "indices" ("id", "code", "name_en", "name_ar", "publisher", "publisher_url", "methodology_summary_en", "methodology_summary_ar", "scale", "score_min", "score_max", "higher_is_better", "frequency", "latest_year", "responsible_entity_id", "linked_node_ids_json", "category", "is_active", "source_notes", "created_at", "updated_at", "sdg_goal", "linked_statistics_indicator_id", "target_value", "target_year", "forecast_mode", "forecast_enabled") VALUES
('01M4D6BSMX8S5R7AA89DF8G6V2', 'hdi', 'Human Development Index', 'مؤشر التنمية البشرية', 'UNDP', 'https://hdr.undp.org/', 'Geometric mean of normalized indices for health (life expectancy), education (expected and mean years of schooling) and standard of living (GNI per capita, PPP). Annual; the 2025 report carries data through 2023.', 'متوسط هندسي لمؤشرات معيارية للصحة (العمر المتوقع) والتعليم (سنوات الدراسة المتوقعة والفعلية) ومستوى المعيشة (نصيب الفرد من الدخل القومي الإجمالي). يصدر سنويًا، وتغطي نسخة 2025 بيانات عام 2023.', 'both', 0.0, 1.0, 1, 'annual', 2023, NULL, NULL, 'human', 1, 'Bulk CSV from the HDR data center (HDR25 composite time series). Ranks for non-latest years are derived by sorting the official values.', '2026-10-08T07:24:08.222Z', '2026-10-08T07:24:10.234Z', NULL, NULL, NULL, NULL, NULL, 1),
('01M4D6BSMYYVZSFPYJTSH20DK3', 'cpi', 'Corruption Perceptions Index', 'مؤشر مدركات الفساد', 'Transparency International', 'https://www.transparency.org/en/cpi', 'Aggregates up to 13 expert and business surveys of perceived public-sector corruption to a 0-100 scale (100 = very clean). Comparable across years from 2012.', 'يجمع حتى 13 تقييمًا من الخبراء واستطلاعات رجال الأعمال حول مدركات الفساد في القطاع العام على مقياس من 0 إلى 100 (حيث 100 الأكثر نزاهة). قابل للمقارنة عبر السنوات منذ 2012.', 'both', 0.0, 100.0, 1, 'annual', 2025, NULL, NULL, 'governance', 1, 'Official results workbook (timeseries sheet, 2012 onward).', '2026-10-08T07:24:08.222Z', '2026-10-08T07:24:19.107Z', NULL, NULL, NULL, NULL, NULL, 1),
('01M4D6BSMYPT2916QK61ZSH54T', 'epi', 'Environmental Performance Index', 'مؤشر الأداء البيئي', 'Yale University', 'https://epi.yale.edu/', 'Biennial scorecard of proximity to environmental targets over about 47 indicators in climate, environmental health and ecosystem vitality, normalized 0-100. Methodology changes between editions.', 'بطاقة نتائج تصدر كل سنتين لقياس الاقتراب من الأهداف البيئية عبر نحو 47 مؤشرًا في المناخ والصحة البيئية وحيوية النظم الإيكولوجية، بدرجات معيارية من 0 إلى 100. تتغير المنهجية بين النسخ.', 'both', 0.0, 100.0, 1, 'biennial', NULL, NULL, '["01M4D6BHK91J1SNCZBB60FXBKF","01M4D6BHK9V5W2W6ZQ2N845KPC"]', 'environment', 1, '2026 edition from the official results workbook (ranks derived by sorting the official scores); earlier editions from the research pass.', '2026-10-08T07:24:08.222Z', '2026-10-08T07:24:08.234Z', NULL, NULL, NULL, NULL, NULL, 1),
('01M4D6BSMYYVV22C28PBMSN8SK', 'sdg_index', 'SDG Index', 'مؤشر أهداف التنمية المستدامة', 'SDSN Sustainable Development Report', 'https://dashboards.sdgindex.org/', 'Overall score of the Sustainable Development Report''s SDG Index: the average of the 17 goal scores, each an average of normalized indicators on a 0 to 100 scale where 100 means the SDG target is reached, for every UN member state with sufficient data (about 167). Annual, with a published rank.', 'الدرجة الكلية لمؤشر أهداف التنمية المستدامة في تقرير التنمية المستدامة: متوسط درجات الأهداف السبعة عشر، وكل منها متوسط مؤشرات معيارية على مقياس من 0 إلى 100 حيث تعني 100 بلوغ الغاية الأممية، لكل دولة عضو في الأمم المتحدة تتوافر لها بيانات كافية (نحو 167 دولة). يصدر سنويًا مع ترتيب منشور.', 'both', 0.0, 100.0, 1, 'annual', NULL, NULL, NULL, 'society', 1, 'Full ranked field of editions 2020 to 2026 from the publisher''s edition databases (2026 live download; 2022 to 2025 Wayback copies of the publisher''s files, cited as read; 2021 SDSN GitHub; 2020 sdsna.github.io). Saudi Arabia is read from the same files.', '2026-10-08T07:24:08.222Z', '2026-10-08T07:24:26.830Z', NULL, NULL, NULL, NULL, 'score', 1),
('01M4D6BSMY93ZW227PS12CCE3G', 'sdg_01', 'SDG 1: No Poverty', 'الهدف 1: القضاء على الفقر', 'SDSN Sustainable Development Report', 'https://dashboards.sdgindex.org/', 'Goal 1 score of the Sustainable Development Report''s SDG Index: the average of the goal''s normalized indicators on a 0 to 100 scale, 100 meaning the SDG target is met. Published for every UN member state with data, annually; no goal-level rank is published.', 'درجة الهدف 1 (القضاء على الفقر) في مؤشر أهداف التنمية المستدامة الصادر عن شبكة حلول التنمية المستدامة: متوسط المؤشرات المعيارية للهدف على مقياس من 0 إلى 100، حيث تعني 100 بلوغ الغاية الأممية. تُنشر سنويًا لكل دولة عضو تتوافر لها بيانات، من دون ترتيب على مستوى الهدف.', 'score', 0.0, 100.0, 1, 'annual', NULL, NULL, NULL, 'human', 1, 'Edition databases of the Sustainable Development Report 2020 to 2026 (the 2026 file from the live download, 2022 to 2025 from Wayback copies of the publisher''s files, 2021 from the SDSN GitHub repository, 2020 from sdsna.github.io); goal ranks are derived by sorting the official goal scores, as CR05 does for HDI.', '2026-10-08T07:24:08.222Z', '2026-10-08T07:24:26.831Z', 1, NULL, NULL, NULL, 'score', 1),
