INSERT INTO "knowledge_of_week" ("id", "week_start", "resource_type", "resource_id", "contributor_user_id", "unit_id", "note_en", "note_ar", "set_by", "set_at", "status", "read_count") VALUES
('01M4D6DD5H8BE0E8H3G6VD1VHA', '2026-10-05', 'study', '01M4D6CBR8GP1KPCP9PS33773Z', '01M4D6BGHA1ANAZV0TK6CR8SAW', '01M4D6BGEHC8RJHJPQ0481V7JY', 'A study the whole Office can lean on: the method is transparent, the data are Saudi, and the recommendations name who should act. Read the summary first, then chapter three.', 'دراسة يمكن للمكتب كله أن يستند إليها: منهجها واضح، وبياناتها سعودية، وتوصياتها تسمّي من عليه أن يتصرف. اقرأ الملخص أولًا ثم الفصل الثالث.', '01M4D6BGH96DBS87XWT8FQFFGW', '2026-10-08T07:25:00.977Z', 'active', 0),
('01M4D6DD5H87BSRMHKCQX87X1A', '2026-10-12', 'lesson', '01M4D6BHQVFZEC2HFF6RXJVN9N', '01M4D6BHENXFYQ2E4HXXWJ52XS', '01M4D6BGEMHR52SA8N2ZYYRJDD', 'A lesson we keep relearning. Two minutes to read, and it will change how you plan your next handover.', 'درس نعود إلى تعلّمه كل مرة. قراءته دقيقتان، وسيغيّر طريقتك في الاستعداد للتسليم القادم.', '01M4D6BGHA1ANAZV0TK6CR8SAW', '2026-10-08T07:25:00.977Z', 'scheduled', 0),
('01M4D6DD5JVMBX6WBS7FNKW8PG', '2026-09-28', 'document', '01M4D6CVT6SH9Y88K1S9W4NVS6', '01M4D6BGH96DBS87XWT8FQFFGW', '01M4D6BGEN9QDGX3095WSWMVDJ', 'The clearest picture of where the numbers stand this quarter. Keep it open when you write your next brief.', 'أوضح صورة لموقع الأرقام هذا الربع. أبقِه مفتوحًا عندما تكتب موجزك القادم.', '01M4D6BGHA1ANAZV0TK6CR8SAW', '2026-09-25T09:00:00.000Z', 'archived', 9),
('01M4D6DD674X243VPV7Y69ZC5K', '2026-09-21', 'study', '01M4D6CBRC9738K0RXSMBP75D7', '01M4D6BGHA1ANAZV0TK6CR8SAW', '01M4D6BGEHC8RJHJPQ0481V7JY', 'An evaluation that tells us what worked and, more usefully, what did not. The findings section is worth the whole read.', 'تقييم يخبرنا بما نجح، والأهم بما لم ينجح. قسم النتائج يستحق القراءة كاملة.', '01M4D6BGH96DBS87XWT8FQFFGW', '2026-09-18T09:00:00.000Z', 'archived', 12),
('01M4D6DD71W676MH95FZWCQA4W', '2026-09-14', 'lesson', '01M4D6BHQPJ17BARSK0K6YB2MV', '01M4D6BHEP9TW2034D56782GZ9', '01M4D6BGEJJ8DT77CSYCK82ZBV', 'Short, specific and already reused by three teams. If you run projects, this one is for you.', 'قصير ومحدد وأعادت استخدامه ثلاثة فرق بالفعل. إن كنت تدير مشاريع فهذا الدرس لك.', '01M4D6BGHA1ANAZV0TK6CR8SAW', '2026-09-11T09:00:00.000Z', 'archived', 6),
('01M4D6DD7HDG5KZVBVAYQ78CSM', '2026-09-07', 'report', '01M4D6DA34MAXMXZ44RWKN39YY', '01M4D6BGH96DBS87XWT8FQFFGW', '01M4D6BGEN9QDGX3095WSWMVDJ', 'Our first report generated inside EnviroAI and published to Institutional Memory. Read it for the content, and for what the tool can now do.', 'أول تقرير أُنشئ داخل EnviroAI ونُشر في الذاكرة المؤسسية. اقرأه لمحتواه، ولما صار بمقدور الأداة أن تفعله.', '01M4D6BGHA1ANAZV0TK6CR8SAW', '2026-09-04T09:00:00.000Z', 'archived', 8);
